entries[138609] = { ["name"] = "Materientausch", ["text"] = "Wirken in 0.5 sek.\nDestabilisiert die Materie des anvisierten Ziels. Wenn dieser Effekt gebannt wird, tauscht das Ziel seinen Standort mit seinem am weitesten entfernten Verbündeten, und beide erleiden gleichmäßig zwischen ihnen verteilten Arkanschaden in Höhe der maximalen Gesundheit des Ziels. Der Anteil des Gesamtschadens, der auf den Verbündeten des Ziels übertragen wird, erhöht sich mit jeder Sekunde." }
entries[138610] = { ["name"] = "Flammender Kern", ["text"] = "Sofort\nJeder erfolgreiche Einsatz von 'Flammen rufen' und 'Ausbruch' erhöht den verursachten Schaden für 45 Sek. um 10%. Wenn 'Flammender Kern' 5 Stapel erreicht, wird der Effekt aufgehoben und es wird 'Geschmolzener Beschuss' ausgelöst." }
